import sys;sys.path.insert(0,__import__('os').path.dirname(__file__));from mk import I

I('30A-01',"예상 오답 **22** — 극댓값 $t=4$에서 $g(4)$를 $3$으로 세는 경우 · **17** — 마지막에 $a$를 더하지 않은 경우",
 ["접선이 점 $(0,t)$를 지난다는 말은 **접선의 $y$절편이 $t$**라는 뜻입니다. 접점 $s$마다 $y$절편 $h(s)$가 하나씩 정해지니, $g(t)$는 결국 ‘$h(s)=t$의 실근의 개수’를 세는 함수가 됩니다.",
  "30번 자리의 전형: 개수 함수 $g(t)$ → 곡선 $y=h(s)$와 수평선 $y=t$의 교점 → 불연속점은 극값과 점근선 높이. 조건 (가)·(나)가 $a$를 하나로 고정합니다."],
 {'C1':("함수",r"$f(x)=(x+a)e^{-x}$. $a$가 미지수라 그래프 모양이 아직 정해지지 않았습니다. 뒤의 조건으로 $a$를 잡아야 합니다."),
  'C2':("개수 함수의 정의",r"접점 $(s,f(s))$의 접선 $y=f'(s)(x-s)+f(s)$에 $x=0$을 넣으면 $y$절편 $h(s)=f(s)-sf'(s)$. 이것이 $t$와 같아지는 $s$의 개수가 $g(t)$입니다."),
  'C4':("(가) 불연속점 2개",r"$h$의 극값 $a$, $(4-a)e^{a-2}$와 점근선 높이 $0$, 이 세 높이에서 개수가 바뀝니다. 그런데 2개뿐이라면 셋 중 두 개가 **겹쳐야** 합니다."),
  'C5':("(나) $g(1)=3$",r"$a$의 후보가 둘($0$, $4$) 남을 때 하나를 떨어뜨리는 확인 조건입니다."),
  'C6':("묻는 것",r"$a$와 $g(1)$부터 $g(10)$까지의 합. 경계값 $t=4$에서 $g$가 얼마인지가 승부처입니다.")},
 [("접선의 $y$절편 함수",[r"점 $(s,f(s))$의 접선이 $(0,t)$를 지남 ⇔ $t=f(s)-sf'(s)$.",r"‘한 점에서 그을 수 있는 접선의 개수’는 언제나 이렇게 접점 $s$에 대한 방정식의 근의 개수로 바뀝니다."]),
  ("개수 함수의 불연속점",[r"$g(t)$는 $y=h(s)$와 $y=t$의 교점 개수. 개수가 변하는 높이는 **극댓값·극솟값·점근선 높이**뿐입니다.",r"$h(s)\to0$ ($s\to\infty$)이므로 $t=0$은 항상 후보입니다."])],
 [("접선의 $y$절편을 $h(s)$로",['C2']),("$h(s)$ 증감과 극값",['C1','C2']),("불연속점이 2개가 되려면",['C4']),("$a=0$ 탈락",['C5']),("$a=4$에서 $g(t)$ 표",['C2','C5']),("합 계산",['C6'])],
 [("극값끼리 겹치는 경우를 빼먹기",'C4',[r"불연속 후보 $0,\ a,\ (4-a)e^{a-2}$ 중 두 개가 같아야 합니다. $a=0$이면 $h(0)=0$, $a=4$이면 $(4-a)e^{a-2}=0$.",r"후보 둘을 다 찾고 (나)로 하나를 버리는 순서를 지키세요."]),
  ("경계 $t=4$에서의 개수",'C6',[r"$t=4$는 극댓값이라 수평선이 꼭대기에 **접합니다**. 교점은 접점 $1$개 + 왼쪽 가지 $1$개 = $2$개. $3$으로 세면 답이 $22$가 됩니다."]),
  ("$t=0$과 $t>4$의 왼쪽 가지",'C2',[r"$s\to-\infty$에서 $h(s)\to\infty$이므로 $t>4$여도 왼쪽에서 교점이 하나 있습니다. 그래서 $g(t)=1$이지 $0$이 아닙니다."])],
 [("변형 · 개수가 2인 $t$",[r"함수 $f(x)=(x+4)e^{-x}$에 대하여 곡선 $y=f(x)$ 위의 점 $(s,f(s))$에서의 접선이 점 $(0,t)$를 지나도록 하는 실수 $s$의 개수를 $g(t)$라 하자. $g(t)=2$를 만족시키는 모든 실수 $t$의 값의 합을 구하시오."],4,r"$h(s)=(s+2)^2e^{-s}$: 극소 $0$ ($s=-2$, 접함 → $g(0)=1$), 극대 $4$ ($s=0$). $g(t)=2$는 $t=4$뿐.")],
 "점에서 긋는 접선의 개수 = 접선의 $y$절편 함수 $h(s)$와 수평선의 교점 개수. 극값에서 접하면 하나가 줄어든다.")

I('30A-02',"예상 오답 **6** — $a>0$로 두고 계산한 경우 · **9** — $a=-3$의 부호를 빼서 $p+q+a$로 계산한 경우",
 ["$g(t)=0$인 범위가 **음수 쪽에 구간**으로 주어졌다는 것이 첫 열쇠입니다. 분모가 항상 양수면 $f>0$이라 음수 값을 못 가지니, 분모 $x^2+a$가 $0$이 되는 점(수직점근선)이 있어야 합니다. 즉 $a<0$.",
  "극댓값이 정확히 $-\\dfrac1{2e}$가 되는 조건을 $x_1$에 대한 방정식으로 바꾸고, 그 방정식의 근을 ‘눈으로’ 찾는 문제입니다."],
 {'C1':("함수",r"$f(x)=\dfrac{e^x}{x^2+a}$. $a$의 부호가 그래프의 모양(점근선 유무)을 결정합니다."),
  'C2':("개수 함수",r"$g(t)$ = 곡선 $y=f(x)$와 직선 $y=t$의 교점 개수."),
  'C3':("$g(t)=0$인 범위",r"$-\dfrac1{2e}<t\le0$에서 교점이 없다 ⇒ 음수 값은 $-\dfrac1{2e}$ 이하만 가지고, $0$은 못 가짐. 이 값이 가운데 구간의 **극댓값**입니다."),
  'C6':("묻는 것",r"$g(t)=3$인 범위 $t>\dfrac{e^p}{q}$. 오른쪽 가지의 극솟값이 $\dfrac{e^p}{q}$입니다.")},
 [("분수함수의 정의역과 점근선",[r"$x^2+a=0$이 실근을 가지면 $x=\pm\sqrt{-a}$에 수직점근선이 생기고 그래프가 세 조각으로 나뉩니다.",r"가운데 조각에서는 분모가 음수라 $f<0$."]),
  ("극값 계산의 지름길",[r"$f'(x_1)=0$이면 $x_1^2+a=2x_1$이므로 $f(x_1)=\dfrac{e^{x_1}}{2x_1}$. 극값을 구할 때 극점 조건을 대입해 식을 줄이세요."])],
 [("$a\\ge0$이면 모순",['C1','C3']),("$a<0$일 때 개형",['C1','C2']),("극댓값 $=-\\frac1{2e}$로 $a$ 결정",['C3']),("오른쪽 가지의 극솟값",['C2','C6']),("답",['C6'])],
 [("$e^{x+1}+x=0$을 푸는 법",'C3',[r"대수적으로 풀리지 않습니다. 왼쪽이 증가함수임을 보이고 $x=-1$을 **대입해서 찾는** 것이 정석입니다."]),
  ("왼쪽 조각의 교점을 빼먹기",'C6',[r"$x<-\sqrt3$에서 $f$는 $0$에서 $\infty$까지 모든 양수를 가집니다. 그래서 $t>0$이면 왼쪽에서 항상 $1$개. 오른쪽 $2$개와 합쳐 $3$개."]),
  ("$-a$와 $a$",'C6',[r"$a=-3$이므로 $p+q-a=3+6+3$. 부호 처리에서 자주 틀립니다."])],
 [("변형 · 상수를 바꾸면",[r"함수 $f(x)=\dfrac{e^x}{x^2-15}$에 대하여 방정식 $f(x)=t$의 서로 다른 실근의 개수를 $g(t)$라 하자. $g(t)=3$을 만족시키는 실수 $t$의 값의 범위가 $t>\dfrac{e^p}{q}$일 때, $p+q$의 값을 구하시오. (단, $p$, $q$는 자연수)"],15,r"$x^2-2x-15=(x-5)(x+3)$, 오른쪽 극솟값 $f(5)=\dfrac{e^5}{10}$ → $15$.")],
 "음수 값을 갖는 구간이 있다 = 분모가 0이 되는 점이 있다. 극값은 극점 조건을 대입해 줄여서 계산한다.")

I('30A-03',"예상 오답 **8** — $\\beta$를 $f$의 최댓값이 아닌 $g$의 극솟값으로 바꿔 쓴 경우 · **4** — $e$를 곱하지 않은 경우",
 ["합성함수 $g=f\\circ f$의 극값 문제. $g'(x)=f'(f(x))f'(x)$이므로 $g'=0$인 점은 **$f'(x)=0$인 점**과 **$f(x)$가 $f$의 극점이 되는 점** 두 종류입니다.",
  "극솟값 $\\frac4e$가 ‘$a^2e^{1-a}$의 최댓값’과 같다는 것을 알아채면 $a$가 바로 나옵니다."],
 {'C1':("함수",r"$f(x)=axe^{1-x}$, $x=1$에서 최댓값 $a$."),
  'C2':("극솟값 조건",r"$g(1)=f(f(1))=f(a)=a^2e^{1-a}=\dfrac4e$. 이 값이 $a^2e^{1-a}$의 최댓값이라 $a=2$로 정해집니다."),
  'C3':("묻는 것",r"$g(x)=t$가 네 실근을 갖는 범위 → $g$의 개형에서 극솟값과 극댓값 사이.")},
 [("합성함수의 미분",[r"$g'(x)=f'(f(x))\cdot f'(x)$. 두 인수의 부호를 따로 보고 곱합니다.",r"$f(x)=1$이 되는 $x$(안쪽 값이 $f$의 극점)에서도 $g'=0$."]),
  ("최댓값과 같다 ⇒ 미지수 결정",[r"$a^2e^{1-a}$의 최댓값이 $\frac4e$ ($a=2$). 같은 값이 주어지면 $a$는 그 최대점밖에 없습니다."])],
 [("$f$의 성질과 $g'$",['C1']),("$a=2$ 결정과 극소 확인",['C2']),("$g$의 증감",['C2']),("극값과 범위",['C3']),("답",['C3'])],
 [("$x=1$이 정말 극소인가",'C2',[r"$a=2$일 때 $x=1$ 근처에서 $f(x)\approx2>1$이므로 $f'(f(x))<0$. 따라서 $g'$의 부호는 $f'(x)$와 반대: 왼쪽 음, 오른쪽 양 → 극소. 확인을 건너뛰면 근거 없는 답이 됩니다."]),
  ("극댓값은 두 개, 값은 같다",'C3',[r"$f(x)=1$인 $x_1,x_2$에서 $g=f(1)=2$로 극댓값이 같습니다. 그래서 수평선이 $\frac4e$와 $2$ 사이일 때 네 번 만납니다."])],
 [("변형 · $a=3$",[r"함수 $f(x)=3xe^{1-x}$에 대하여 $g(x)=f(f(x))$라 하자. 방정식 $g(x)=t$가 서로 다른 네 실근을 갖도록 하는 실수 $t$의 범위가 $\alpha<t<\beta$일 때, $e^2\alpha\beta$의 값을 구하시오."],27,r"$g(1)=f(3)=\dfrac9{e^2}$ (극소), $f(x)=1$인 점에서 극대 $f(1)=3$. $e^2\times\dfrac9{e^2}\times3=27$.")],
 "합성함수의 극점 = 바깥 함수의 극점 + 안쪽 함수가 바깥 극점 값을 지나는 점.")
